r(.16,1,.3,1),opacity .45s ease}#nocAdsNote.on .panel{transform:none;opacity:1}#nocAdsNote.out .panel{transform:translateY(22px) scale(.98);opacity:0;transition-duration:.42s,.32s}#nocAdsNote .panel>*{opacity:0;transform:translateY(12px);transition:opacity .45s ease,transform .6s cubic-bezier(.16,1,.3,1)}#nocAdsNote.on .panel>*{opacity:1;transform:none}#nocAdsNote.on .kicker{transition-delay:.06s}#nocAdsNote.on h2{transition-delay:.12s}#nocAdsNote.on .lead{transition-delay:.18s}#nocAdsNote.on .offer{transition-delay:.26s}#nocAdsNote.on .ok{transition-delay:.34s}#nocAdsNote .kicker{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#b8b0da;font-weight:600}#nocAdsNote h2{margin:8px 0 0;font-size:28px;line-height:1.15;font-weight:600;letter-spacing:-.03em}#nocAdsNote .lead{margin:12px 0 0;color:#b7b3c7}#nocAdsNote .offer{margin-top:22px;padding:16px 16px 14px;border-radius:0;background:rgba(184,176,218,.08);border:1px solid rgba(184,176,218,.18)}#nocAdsNote .offer strong{display:block;font-size:15px;color:#eae6ff}#nocAdsNote .offer p{margin:6px 0 12px;color:#b7b3c7;font-size:14px}#nocAdsNote .offer a{display:inline-flex;align-items:center;color:#14121c;background:#b8b0da;text-decoration:none;font-weight:600;font-size:13px;padding:8px 12px;border-radius:0}#nocAdsNote .ok{margin-top:18px;width:100%;padding:12px 16px!important;border:0!important;border-radius:0!important;background:#b8b0da!important;color:#14121c!important;font:600 14px/1 inherit;cursor:pointer}#nocAdsNote .ok:hover{background:#cdc4ff!important}@media (max-width:720px){#nocAdsNote{padding:14px}#nocAdsNote h2{font-size:24px}#nocAdsNote .panel{padding:24px 20px 18px;border-radius:0}}@media (prefers-reduced-motion:reduce){#nocAdsNote,#nocAdsNote .panel,#nocAdsNote .panel>*{transition:none}}#nocAdsNote .panel{position:relative;overflow:hidden}#nocAdsNote .orb{position:absolute;border-radius:50%;pointer-events:none}#nocAdsNote .orb.a{width:220px;height:220px;right:-84px;top:-96px;background:radial-gradient(circle,rgba(184,176,218,.55),rgba(184,176,218,0) 68%)}#nocAdsNote .orb.b{width:64px;height:64px;right:18px;top:18px;border:1px solid rgba(184,176,218,.55)}#nocAdsNote .orb.c{width:12px;height:12px;left:22px;top:22px;background:#eae6ff}#nocAdsNote .view{position:relative;z-index:1}#nocAdsNote .perks{list-style:none;margin:18px 0 0;padding:0;display:grid;gap:10px}#nocAdsNote .perks li{display:flex;align-items:center;gap:10px;font-size:14px;color:#eae6ff}#nocAdsNote .perks i{width:8px;height:8px;border-radius:50%;background:#b8b0da;box-shadow:0 0 0 4px rgba(184,176,218,.16);flex:none}#nocAdsNote .actions{display:flex;gap:10px;margin-top:22px}#nocAdsNote .actions a,#nocAdsNote .actions button{flex:1;display:flex;align-items:center;justify-content:center;box-sizing:border-box;min-height:42px;padding:12px 14px;border-radius:0;text-decoration:none;font:600 13px/1 inherit;cursor:pointer}#nocAdsNote .actions a{background:#b8b0da!important;color:#14121c!important;border:0!important;border-radius:0!important;padding:12px 14px!important;text-decoration:none!important}#nocAdsNote .actions a:hover{background:#cdc4ff!important}#nocAdsNote .ghost{background:transparent!important;color:#eae6ff!important;border:1px solid rgba(184,176,218,.45)!important;border-radius:0!important;padding:12px 14px!important}#nocAdsNote input{width:100%;box-sizing:border-box;margin-top:14px;border-radius:0;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.03);color:#eae6ff;padding:11px 12px;font:inherit}#nocAdsNote .msg{margin-top:10px;font-size:13px;color:#b7b3c7}</style><script>(function(){try{
if(/(?:^|; )noc_ads_ack=1(?:;|$)/.test(document.cookie))return;
