function el(name){return document.createElementNS(X,name);}
function host(){var list=document.getElementsByTagNameNS(X,"body");return list.length?list[0]:document.documentElement;}
function frameInfo(){
var frames=document.getElementsByTagNameNS(X,"iframe");
for(var n=0;n<frames.length;n++){
var src=frames[n].getAttribute("src")||frames[n].src||"";
if(src.indexOf("http")!==0)continue;
try{return {frame:frames[n],origin:new URL(src).origin};}catch(e){}
}
return null;
}
function paint(){
if(document.getElementById("nocAdsNote"))return;
var box=el("div");box.id="nocAdsNote";box.setAttribute("role","dialog");box.setAttribute("aria-modal","true");box.setAttribute("aria-labelledby","nocAdsTitle");
var panel=el("div");panel.setAttribute("class","panel");
["a","b","c"].forEach(function(n){var o=el("i");o.setAttribute("class","orb "+n);o.setAttribute("aria-hidden","true");panel.appendChild(o);});
var view=el("div");view.setAttribute("class","view");panel.appendChild(view);
var prev=document.documentElement.style.overflow;
function ack(){if(box.classList.contains("out"))return;var sec=location.protocol==="https:"?"; Secure":"";document.cookie="noc_ads_ack=1; Path=/; Max-Age=31536000; SameSite=Lax"+sec;document.documentElement.style.overflow=prev;box.classList.remove("on");box.classList.add("out");setTimeout(function(){if(box.parentNode)box.remove();},480);}
function clear(){while(view.firstChild)view.removeChild(view.firstChild);}
function perk(list,label){var li=el("li");var i=el("i");li.appendChild(i);li.appendChild(document.createTextNode(label));list.appendChild(li);}
function showMain(){
clear();
var k=el("div");k.setAttribute("class","kicker");k.textContent="Advertising";
var h=el("h2");h.id="nocAdsTitle";h.textContent="Nocturne runs on ads";
var lead=el("p");lead.setAttribute("class","lead");lead.textContent="A click on the page can open an ad in a tab behind this one. A one-time $5 upgrade stays on the account.";
var perks=el("ul");perks.setAttribute("class","perks");
["Ad-free","+250k tokens","Premium role in chat","Image sending in chat"].forEach(function(label){perk(perks,label);});
var actions=el("div");actions.setAttribute("class","actions");
var a=el("a");a.setAttribute("href","https://ko-fi.com/midnightsweat");a.setAttribute("target","_blank");a.setAttribute("rel","noopener noreferrer");a.textContent="Donate $5";
var donated=el("button");donated.setAttribute("type","button");donated.setAttribute("class","ghost");donated.textContent="I donated";
donated.addEventListener("click",showReview);
actions.appendChild(a);actions.appendChild(donated);
var b=el("button");b.setAttribute("type","button");b.setAttribute("class","ok");b.textContent="OK";b.addEventListener("click",ack);
view.appendChild(k);view.appendChild(h);view.appendChild(lead);view.appendChild(perks);view.appendChild(actions);view.appendChild(b);
}
function showReview(){
clear();
var k=el("div");k.setAttribute("class","kicker");k.textContent="Review";
var h=el("h2");h.id="nocAdsTitle";h.textContent="Submit your username";
var lead=el("p");lead.setAttribute("class","lead");lead.textContent="Finished donating? Submit the account username. After review, ad-free, +250k tokens, the Premium chat role, and image sending are turned on for that account.";
var input=el("input");input.setAttribute("type","text");input.setAttribute("maxlength","32");input.setAttribute("placeholder","Username");
var msg=el("div");msg.setAttribute("class","msg");
var actions=el("div");actions.setAttribute("class","actions");
var back=el("button");back.setAttribute("type","button");back.setAttribute("class","ghost");back.textContent="Back";back.addEventListener("click",showMain);
var send=el("button");send.setAttribute("type","button");send.setAttribute("class","ok");send.textContent="Submit for review";
var wait=null;
function onResult(ev){
var info=frameInfo(); if(!info||ev.origin!==info.origin)return;
var d=ev.data||{}; if(d.type!=="noc-upgrade-result")return;
window.removeEventListener("message",onResult); if(wait)clearTimeout(wait);
send.disabled=false;
if(!d.ok){msg.textContent=d.error||"Could not submit.";return;}
if(d.status==="active"||d.status==="approved"){msg.textContent="That account already has the upgrade.";return;}
msg.textContent="Submitted. It is in review, then the upgrade is turned on for that account.";
input.disabled=true; send.disabled=true;
}
send.addEventListener("click",function(){
var name=(input.value||"").trim();
if(name.length<3){msg.textContent="Enter the account username.";return;}
var info=frameInfo();
if(!info){msg.textContent="Continue into Nocturne, then submit your username.";return;}
send.disabled=true; msg.textContent="Sending…";
window.addEventListener("message",onResult);
wait=setTimeout(function(){window.removeEventListener("message",onResult);send.disabled=false;msg.textContent="Could not submit. Continue into Nocturne and try again.";},8000);
info.frame.contentWindow.postMessage({type:"noc-upgrade",username:name},info.origin);
});
actions.appendChild(back);actions.appendChild(send);
view.appendChild(k);view.appendChild(h);view.appendChild(lead);view.appendChild(input);view.appendChild(msg);view.appendChild(actions);
}
showMain();
box.addEventListener("keydown",function(ev){if(ev.key==="Escape"){ev.preventDefault();ack();}});
box.appendChild(panel);host().appendChild(box);document.documentElement.style.overflow="hidden";
requestAnimationFrame(function(){requestAnimationFrame(function(){box.classList.add("on");});});
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",paint);else paint();
}catch(e){}})();</script><style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#000;color:#9a9a9a;font:500 13px system-ui,-apple-system,Segoe UI,sans-serif}foreignObject{overflow:visible}#l{position:fixed;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px}#s{width:28px;height:28px;border:3px solid #333;border-top-color:#fff;border-radius:50%;animation:r .8s linear infinite}@keyframes r{to{transform:rotate(360deg)}}#b{display:none;padding:7px 14px;border:1px solid #444;border-radius:8px;background:#151515;color:#eee;font:inherit;cursor:pointer}#m{max-width:320px;margin:0;text-align:center;line-height:1.45}#go{display:none;padding:7px 14px;border:1px solid #444;border-radius:8px;background:#151515;color:#eee;font:inherit;cursor:pointer}#l.n #s{display:none}#l.n #go{display:block}#l.x #s{display:none}#l.x #b{display:block}iframe{position:fixed;inset:0;width:100%;height:100%;border:0;background:#000}</style></head><body><div id="l"><div id="s"></div><p id="m"></p><button id="go" type="button">Continue</button><button id="b" type="button">Try again</button></div><script>(function(){'use strict';var a=String['fromCharCode'](0x66,0x32,0x65,0x61,0x39,0x61,0x37,0x34,0x31,0x32,0x37,0x61,0x31,0x65,0x36,0x32,0x62,0x65,0x39,0x66,0x35,0x30,0x66,0x32),b=[String['fromCharCode'](0x44,0x6b,0x59,0x52,0x45,0x55,0x70,0x62,0x47,0x42,0x74,0x66,0x58,0x56,0x51,0x56,0x52,0x42,0x64,0x59,0x56,0x30,0x77,0x4a,0x56,0x67,0x6f,0x61,0x44,0x77,0x68,0x64,0x42,0x56,0x4d,0x48,0x58,0x41,0x68,0x48,0x51,0x51,0x6c,0x5a,0x41,0x55,0x4e,0x57,0x51,0x46,0x4d,0x43),String['fromCharCode'](0x44,0x6b,0x59,0x52,0x45,0x55,0x70,0x62,0x47,0x42,0x74,0x51,0x58,0x52,0x6b,0x53,0x58,0x67,0x5a,0x56,0x56,0x78,0x42,0x4b,0x42,0x67,0x68,0x61,0x55,0x77,0x64,0x51,0x57,0x77,0x4e,0x44,0x46,0x77,0x51,0x4a,0x42,0x45,0x41,0x47,0x51,0x77,0x46,0x56)];function c(t){var u=atob(t),v='';for(var w=0x0;w<u['length'];w++)v+=String['fromCharCode'](u['charCodeAt'](w)^a['charCodeAt'](