      const VAULT_HTML = "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width,initial-scale=1" />
    <title>The Vault</title>
    <link id="site-favicon" rel="icon" type="image/png" href="https://s3.amazonaws.com/cstest/mb/2025/01/GraceChristian_Eagles_Logo2.png.220x220_q95.png">
    <style>

        #constellation-canvas{
            position:fixed;
            inset:0;
            z-index:0;
            pointer-events:none;
        }

        /* Red & black theme inspired by provided design; preserves original layout behavior */
        :root{--bg:#0b0b0b;--panel:#0f0f0f;--accent:#1e90ff;--muted:rgba(255,255,255,0.75);--glass:rgba(255,255,255,0.03)}
        *{box-sizing:border-box}
        html,body{
          min-height:100%;
          margin:0;
          font-family:Inter,Segoe UI,Roboto,Arial,sans-serif;

          background:
            radial-gradient(circle at 10% 10%, rgba(30,144,255,0.05), transparent 20%),
            linear-gradient(135deg,#2a2e45 0%, #31457a 50%, #2f5194 100%);

          background-repeat:no-repeat;

          color:var(--muted)
        }
        .sidebar{position:fixed;left:12px;top:12px;width:76px;height:calc(100vh - 24px);background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.2));backdrop-filter:blur(6px);padding:14px;border-radius:10px;border:2px solid rgba(30,144,255,0.06);overflow:auto;box-shadow:0 10px 30px rgba(0,0,0,0.7)}
        .sidebar-btn{background:transparent;border:none;color:var(--muted);font-weight:800;padding:8px;margin:6px 0;border-radius:8px;cursor:pointer;width:46px;height:36px;display:flex;align-items:center;justify-content:center;border:2px solid transparent}
        .sidebar-btn:not(.empty):hover{background:rgba(30,144,255,0.06);color:var(--accent);transform:translateX(4px)}
        .sidebar-btn.empty{opacity:0.18;cursor:default}

        .main-content{margin-left:110px;margin-right:300px;padding:28px 36px}
        header{display:flex;align-items:center;gap:16px;margin-bottom:18px}
        .logo{width:68px;height:68px;border-radius:8px;overflow:hidden;border:2px solid rgba(30,144,255,0.18)}
        .logo img{width:100%;height:100%;object-fit:cover}
        h1{margin:0;font-size:20px;letter-spacing:0.6px}
        .sub{font-size:13px;color:rgba(255,255,255,0.6)}

        .section-wrap{max-width:1200px;margin:8px auto}
        .letter-section{background:linear-gradient(180deg, rgba(0,0,0,0.12), rgba(0,0,0,0.06));border-left:4px solid rgba(30,144,255,0.22);padding:12px;border-radius:10px;margin-bottom:18px}
        .letter-header{font-size:22px;font-weight:800;color:var(--accent);margin-bottom:10px}
        .buttons-container{display:flex;flex-direction:column;gap:8px}
        input[type="button"]{background:transparent;border:2px solid rgba(30,144,255,0.18);padding:12px 14px;border-radius:8px;color:var(--muted);font-weight:700;text-align:left;cursor:pointer}
        input[type="button"]:hover{background:rgba(30,144,255,0.04);color:var(--accent);transform:translateY(-2px)}

        .links{margin-left:auto;display:flex;gap:12px;align-items:center}
        .link{color:var(--accent);text-decoration:none}



        @media (max-width:860px){.main-content{margin-left:88px;padding:18px}.logo{width:54px;height:54px}}

/* SETTINGS MODAL */
.settings-gear{background:none;border:none;cursor:pointer;font-size:20px;color:rgba(255,255,255,0.5);padding:6px;border-radius:8px;transition:all 0.15s;line-height:1;}
.settings-gear:hover{color:var(--accent);transform:rotate(45deg);}
.settings-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:9998;display:none;align-items:center;justify-content:center;}
.settings-overlay.open{display:flex;}
.settings-modal{background:#0f0f0f;border:2px solid rgba(30,144,255,0.2);border-radius:12px;padding:24px;width:460px;max-width:92%;box-shadow:0 20px 60px rgba(0,0,0,0.8);}
.settings-modal h3{margin:0 0 18px;color:var(--accent);font-size:16px;display:flex;align-items:center;gap:8px;}
.settings-label{font-size:12px;font-weight:700;color:rgba(255,255,255,0.5);text-transform:uppercase;letter-spacing:0.8px;margin:14px 0 6px;}
.settings-input{width:100%;padding:10px 12px;border-radius:8px;border:2px solid rgba(30,144,255,0.15);background:#0b0b0b;color:var(--muted);font-size:13px;}
.settings-input:focus{outline:none;border-color:rgba(30,144,255,0.4);}
.settings-row{display:flex;gap:8px;margin-top:18px;}
.settings-btn{flex:1;padding:10px;border-radius:8px;border:none;font-weight:800;font-size:13px;cursor:pointer;}
.settings-save{background:var(--accent);color:#07060a;}
.settings-reset{background:rgba(255,255,255,0.06);color:rgba(255,100,100,0.9);border:2px solid rgba(255,100,100,0.2);}
.settings-close{background:rgba(255,255,255,0.06);color:var(--muted);border:2px solid rgba(255,255,255,0.08);}
.settings-saved{font-size:12px;color:#4caf50;margin-top:8px;text-align:center;display:none;}

.search-sidebar{
    position:fixed;
    right:12px;
    top:12px;
    width:260px;
    height:calc(100vh - 24px);
    background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.2));
    backdrop-filter:blur(6px);
    padding:14px;
    border-radius:10px;
    border:2px solid rgba(30,144,255,0.06);
    overflow:hidden;
    box-shadow:0 10px 30px rgba(0,0,0,0.7);
    display:flex;
    flex-direction:column;
    gap:10px;
}
.search-input{
    padding:10px;
    border-radius:8px;
    border:2px solid rgba(30,144,255,0.18);
    background:#0b0b0b;
    color:var(--muted);
}
.search-results{
    overflow:auto;
    flex:1;
}
.search-item{
    padding:8px;
    border-radius:6px;
    cursor:pointer;
    font-weight:700;
}
.search-item:hover{
    background:rgba(30,144,255,0.08);
    color:var(--accent);
}
.disguise-btn{
    padding:10px;
    border-radius:8px;
    border:none;
    background:var(--accent);
    color:#07060a;
    font-weight:800;
    cursor:pointer;
}

/* RECENTLY PLAYED */
.recent-section{
    background:linear-gradient(180deg, rgba(30,144,255,0.05), rgba(0,0,0,0.08));
    border-left:4px solid rgba(30,144,255,0.5);
    padding:14px;
    border-radius:10px;
    margin-bottom:22px;
}
.recent-header{
    font-size:14px;
    font-weight:800;
    color:var(--accent);
    text-transform:uppercase;
    letter-spacing:1px;
    margin-bottom:12px;
}
.recent-games{
    display:flex;
    gap:10px;
    flex-wrap:wrap;
}
.recent-card{
    background:rgba(30,144,255,0.06);
    border:2px solid rgba(30,144,255,0.18);
    border-radius:8px;
    padding:10px 14px;
    cursor:pointer;
    font-weight:700;
    font-size:13px;
    color:var(--muted);
    transition:all 0.15s ease;
}
.recent-card:hover{
    background:rgba(30,144,255,0.14);
    color:var(--accent);
    transform:translateY(-2px);
    border-color:rgba(30,144,255,0.4);
}
.recent-empty{
    color:rgba(255,255,255,0.3);
    font-size:13px;
    font-style:italic;
}

/* PINNED GAMES */
.pinned-section{
    background:linear-gradient(180deg, rgba(255,215,0,0.04), rgba(0,0,0,0.08));
    border-left:4px solid rgba(255,200,0,0.5);
    padding:14px;
    border-radius:10px;
    margin-bottom:22px;
}
.pinned-header{
    font-size:14px;
    font-weight:800;
    color:#ffd700;
    text-transform:uppercase;
    letter-spacing:1px;
    margin-bottom:12px;
}
.pinned-games{
    display:flex;
    gap:10px;
    flex-wrap:wrap;
}
.pinned-card{
    background:rgba(255,200,0,0.06);
    border:2px solid rgba(255,200,0,0.25);
    border-radius:8px;
    padding:10px 14px;
    cursor:pointer;
    font-weight:700;
    font-size:13px;
    color:var(--muted);
    transition:all 0.15s ease;
    display:flex;
    align-items:center;
    gap:8px;
}
.pinned-card:hover{
    background:rgba(255,200,0,0.12);
    color:#ffd700;
    transform:translateY(-2px);
    border-color:rgba(255,200,0,0.5);
}
.pinned-card .unpin-btn{
    background:none;
    border:none;
    color:rgba(255,200,0,0.5);
    cursor:pointer;
    font-size:13px;
    padding:0;
    line-height:1;
    transition:color 0.15s;
}
.pinned-card .unpin-btn:hover{
    color:#ffd700;
}
.pinned-empty{
    color:rgba(255,255,255,0.3);
    font-size:13px;
    font-style:italic;
}
.pin-btn{
    padding:8px 10px;
    border-radius:6px;
    border:2px solid rgba(255,200,0,0.2);
    background:transparent;
    color:rgba(255,200,0,0.5);
    cursor:pointer;
    font-size:14px;
    transition:all 0.15s ease;
    line-height:1;
}
.pin-btn:hover{
    background:rgba(255,200,0,0.08);
    color:#ffd700;
    border-color:rgba(255,200,0,0.5);
}
.pin-btn.pinned{
    color:#ffd700;
    border-color:rgba(255,200,0,0.5);
    background:rgba(255,200,0,0.08);
}
.back-link {
    color: #c9cad2; /* default color */
    text-decoration: none; /* optional, removes underline */
    transition: color 0.15s; /* smooth transition on hover */
}

.back-link:hover {
    color: #ffffff; /* color on hover */
}
</style>


</head>
<body>

<canvas id="constellation-canvas"></canvas>
    <!-- Sidebar and content (original functionality preserved) -->
    <div class="sidebar" id="sidebar"></div>

<div class="search-sidebar">
    <input class="search-input" id="searchBox" placeholder="Search games...">
    <button class="disguise-btn" onclick="hideSite()">Hide Site (blocked image)</button>
    <button class="disguise-btn" onclick="openGoogleWindow()">Open Google unbl0cked(broken)</button>
    <button class="disguise-btn" onclick="launchRandomGame()">🎲 Random Game!</button>

    <div class="search-results" id="searchResults"></div>
</div>


    <div class="main-content">
        <header>
            <div class="logo"><img src="https://i.ibb.co/99Lc2mGt/GCSeagle.png" alt="Vault logo"></div>
            <div>
                <h2>The Vault</h2>
                <h3>Version 2.6.23</h3>
