}


function disguiseSite(){
    document.title = "ParentVUE";
    document.getElementById('site-favicon').href =
        "https://va-wjccp-psv.edupoint.com/favicon.ico?regenerateSessionId=true";
}

const searchBox = document.getElementById('searchBox');
const searchResults = document.getElementById('searchResults');

searchBox.addEventListener('input', () => {
    const q = searchBox.value.toLowerCase();
    searchResults.innerHTML = '';
    if(!q) return;

    files.filter(f => f.toLowerCase().includes(q)).slice(0,100).forEach(file => {
        const div = document.createElement('div');
        div.className = 'search-item';
        div.textContent = file.replace(/^cl/i,'');
        div.onclick = () => {
            if(typeof addXP === 'function') addXP(xpPerGame());
            recordRecentGame(file);
            const normalized = file.endsWith('.html') ? file : file + '.html';
            fetch(`https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile/UGS-Files/${encodeURIComponent(normalized)}?t=${Date.now()}`)
              .then(r => r.text())
              .then(t => {
                const w = window.open('about:blank','_blank');
                if(w){ w.document.open(); w.document.write(t); w.document.close(); }
              });
        };
        searchResults.appendChild(div);
    });
});


    function openAboutBlank(){
        const win = window.open("about:blank", "_blank");
        if(win){
            win.document.open();
            win.document.write(document.documentElement.outerHTML);
            win.document.close();
        }
    }

