<script>

function launchRandomGame() {
    if (!files || files.length === 0) return;

    const file = files[Math.floor(Math.random() * files.length)];
    recordRecentGame(file);

    const normalized = file.endsWith('.html') ? file : file + '.html';
    const encoded = encodeURIComponent(normalized);

    fetch(`https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile/UGS-Files/${encoded}?t=${Date.now()}`)
        .then(r => r.text())
        .then(t => {
            const w = window.open('about:blank', '_blank');
            if (w) { w.document.open(); w.document.write(t); w.document.close(); }
        });
}

		function openGoogleWindow(){
    window.open(
        "https://www.google.com",
        "_blank",
        "width=1000,height=700"
    );
}

        const canvas = document.getElementById('constellation-canvas');
        const ctx = canvas.getContext('2d');
        let stars = [];
        const starCount = 125;
        const maxDistance = 150;

        function resize() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }

        class Star {
            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.vx = (Math.random() - 0.5) * 0.5;
                this.vy = (Math.random() - 0.5) * 0.5;
                this.radius = Math.random() * 1.8;
            }
            update() {
                this.x += this.vx;
                this.y += this.vy;
                if (this.x < 0 || this.x > canvas.width) this.vx *= -1;
                if (this.y < 0 || this.y > canvas.height) this.vy *= -1;
            }
            draw() {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
                ctx.fill();
            }
        }

        function initStars() {
            stars = [];
            for (let i = 0; i < starCount; i++) stars.push(new Star());
        }

        function animate() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            stars.forEach(s => { s.update(); s.draw(); });
            for (let i = 0; i < stars.length; i++) {
                for (let j = i + 1; j < stars.length; j++) {
                    const dx = stars[i].x - stars[j].x;
                    const dy = stars[i].y - stars[j].y;
                    const dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist < maxDistance) {
                        const alpha = 1 - (dist / maxDistance);
                        ctx.beginPath();
                        ctx.moveTo(stars[i].x, stars[i].y);
                        ctx.lineTo(stars[j].x, stars[j].y);
                        ctx.strokeStyle = `rgba(255, 255, 255, ${alpha * 0.4})`;
                        ctx.lineWidth = 0.6;
                        ctx.stroke();
                        ctx.closePath();
                    }
                }
            }
            requestAnimationFrame(animate);
        }

// Initialize canvas and stars
resize();
initStars();

// Start animation
animate();

// Resize canvas when the window changes size
window.addEventListener("resize", () => {
    resize();
    initStars(); // regenerate stars so they fill the new space
});

    </script>

<script>
let siteHidden = false;
let overlay = null;
let imgEl = null;

function hideSite(){
  if(!siteHidden){

    imgEl = document.createElement("img");
    imgEl.src = "https://i.postimg.cc/J0ck2C1Y/Screenshot-2026-03-10-at-9-41-57-PM.png";

    Object.assign(imgEl.style,{
      position:"fixed",
      top:"0",
      left:"0",
      width:"100vw",
      height:"100vh",
      objectFit:"cover",
      zIndex:"99998"
    });

    document.body.appendChild(imgEl);

    overlay = document.createElement("div");
    Object.assign(overlay.style,{
      position:"fixed",
      top:"0",
      left:"0",
      width:"100%",
      height:"100%",
      zIndex:"99999",
      background:"transparent",
      cursor:"pointer"
    });

    overlay.onclick = () => {
      imgEl.remove();
      overlay.remove();
      siteHidden = false;
    };

    document.body.appendChild(overlay);

    siteHidden = true;

  } else {

    if(imgEl) imgEl.remove();
    if(overlay) overlay.remove();
    siteHidden = false;

  }
}



</script>

<script>
/* ================= PINNED GAMES ================= */
function getPinnedGames(){
    try{ return JSON.parse(localStorage.getItem("astro_pinned") || "[]"); }
    catch(e){ return []; }
}

function togglePin(file){
    let pinned = getPinnedGames();
    if(pinned.includes(file)){
        pinned = pinned.filter(f => f !== file);
    } else {
        if(pinned.length >= 3){
            alert("You can only pin up to 3 games! Unpin one first.");
            return;
        }
        pinned.push(file);
    }
    localStorage.setItem("astro_pinned", JSON.stringify(pinned));
    renderPinnedGames();
    refreshAllPinButtons();
}

function refreshAllPinButtons(){
    const pinned = getPinnedGames();
    document.querySelectorAll('.pin-btn[data-file]').forEach(btn => {
        const f = btn.dataset.file;
        if(pinned.includes(f)){
            btn.classList.add('pinned');
            btn.title = 'Unpin game';
        } else {
            btn.classList.remove('pinned');
            btn.title = 'Pin game';
        }
    });
}

function renderPinnedGames(){
    const container = document.getElementById("pinnedGames");
    if(!container) return;
    const pinned = getPinnedGames();
    if(pinned.length === 0){
        container.innerHTML = '<span class="pinned-empty">No games pinned yet — pin up to 3 favorites!</span>';
        return;
    }
    container.innerHTML = '';
    pinned.forEach(file => {
        const card = document.createElement('div');
        card.className = 'pinned-card';

        const label = document.createElement('span');
        label.textContent = '📌 ' + file.replace(/^cl/i,'');
        label.style.flex = '1';
        label.style.cursor = 'pointer';
        label.onclick = () => {
            recordRecentGame(file);
            const normalized = file.endsWith('.html') ? file : file + '.html';
            fetch(`https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile/UGS-Files/${encodeURIComponent(normalized)}?t=${Date.now()}`)
                .then(r => r.text())
                .then(t => {
                    const w = window.open('about:blank','_blank');
                    if(w){ w.document.open(); w.document.write(t); w.document.close(); }
                });
        };

        const unpinBtn = document.createElement('button');
        unpinBtn.className = 'unpin-btn';
        unpinBtn.textContent = '✕';
        unpinBtn.title = 'Unpin';
        unpinBtn.onclick = (e) => {
            e.stopPropagation();
            togglePin(file);
        };

        card.appendChild(label);
        card.appendChild(unpinBtn);
        container.appendChild(card);
    });
}

document.addEventListener("DOMContentLoaded", renderPinnedGames);

/* ================= RECENTLY PLAYED ================= */
function getRecentGames(){
    try{ return JSON.parse(localStorage.getItem("astro_recent") || "[]"); }
    catch(e){ return []; }
}

function recordRecentGame(file){
    let recent = getRecentGames();
    recent = recent.filter(f => f !== file);
    recent.unshift(file);
    recent = recent.slice(0, 5);
    localStorage.setItem("astro_recent", JSON.stringify(recent));
    renderRecentGames();
}

function renderRecentGames(){
    const container = document.getElementById("recentGames");
    if(!container) return;
    const recent = getRecentGames();
    if(recent.length === 0){
        container.innerHTML = '<span class="recent-empty">No games played yet — launch one to get started!</span>';
        return;
    }
    container.innerHTML = '';
    recent.forEach(file => {
        const card = document.createElement('div');
        card.className = 'recent-card';
        card.textContent = '▶ ' + file.replace(/^cl/i,'');
        card.onclick = () => {
            recordRecentGame(file);
            const normalized = file.endsWith('.html') ? file : file + '.html';
            fetch(`https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile/UGS-Files/${encodeURIComponent(normalized)}?t=${Date.now()}`)
                .then(r => r.text())
                .then(t => {
                    const w = window.open('about:blank','_blank');
                    if(w){ w.document.open(); w.document.write(t); w.document.close(); }
                });
        };
        container.appendChild(card);
    });
}

document.addEventListener("DOMContentLoaded", renderRecentGames);
</script>

</body>
</html>
";

      const $ = (id) => document.getElementById(id);
      const statusText = $("statusText");

      function updateStatus(msg) {
        if (statusText) statusText.textContent = msg;
      }

      // ---------- Tabs ----------
      let current = null;
      function setTab(name) {
        current = name;
        const mc = name === "mc", br = name === "br";
        $("panelMc").style.display = mc ? "inline" : "none";
        $("panelBr").style.display = br ? "inline" : "none";
        $("backGroup").style.display = name ? "inline" : "none";
        $("tabMcRect").setAttribute("class", "tab" + (mc ? " active" : ""));
        $("tabBrRect").setAttribute("class", "tab" + (br ? " active" : ""));
        $("tabMcText").setAttribute("class", "tt" + (mc ? " active" : ""));
        $("tabBrText").setAttribute("class", "tt" + (br ? " active" : ""));
        $("kicker").textContent = mc ? "MINECRAFT" : br ? "BROWSER / GAMES" : "HOME";
        $("leadText").textContent = mc
          ? "Eaglercraft offline launcher. Cached after the first download."
          : br ? "Game hubs and browser tools, opened in about:blank."
          : "Pick a tab to get started.";
        updateStatus("Ready.");
      }

      // ---------- Eaglercraft cache ----------
      function openDB() {
        return new Promise((resolve, reject) => {
          const req = indexedDB.open(DB_NAME);
          req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
          };
          req.onsuccess = () => {
            const db = req.result;
            if (db.objectStoreNames.contains(STORE_NAME)) {
              resolve(db);
            } else {
              const nextVersion = (db.version || 1) + 1;
              db.close();
              const upReq = indexedDB.open(DB_NAME, nextVersion);
              upReq.onupgradeneeded = (e) => {
                const uDb = e.target.result;
                if (!uDb.objectStoreNames.contains(STORE_NAME)) uDb.createObjectStore(STORE_NAME);
              };
              upReq.onsuccess = () => resolve(upReq.result);
              upReq.onerror = () => reject(upReq.error);
            }
          };
          req.onerror = () => reject(req.error);
        });
      }

      function getStoredGame(db) {
        return new Promise((resolve, reject) => {
          const req = db.transaction(STORE_NAME, "readonly").objectStore(STORE_NAME).get(GAME_KEY);
          req.onsuccess = () => resolve(req.result);
          req.onerror = () => reject(req.error);
        });
      }

      function saveGame(db, content) {
        return new Promise((resolve, reject) => {
          const req = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME).put(content, GAME_KEY);
          req.onsuccess = () => resolve();
          req.onerror = () => reject(req.error);
        });
      }

      function clearStoredGame(db) {
        return new Promise((resolve, reject) => {
          const req = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME).delete(GAME_KEY);
          req.onsuccess = () => resolve();
          req.onerror = () => reject(req.error);
        });
      }

      // ---------- about:blank launching ----------
      function writeToBlank(html, baseHref) {
        const win = window.open("about:blank", "_blank");
        if (!win) {
          updateStatus("Pop-up blocked! Allow pop-ups and try again.");
          return false;
        }
        let out = html;
        if (baseHref && !/<base\s/i.test(out)) out = `<base href="${baseHref}">` + out;
        win.document.open();
        win.document.write(out);
        win.document.close();
        return true;
      }

      async function handleLaunch() {
        try {
          updateStatus("Opening IndexedDB...");
          const db = await openDB();

          updateStatus("Checking cached version...");
          const cachedHtml = await getStoredGame(db);

          if (cachedHtml && !cachedHtml.trim().startsWith("version https://git-lfs.github.com/spec/v1")) {
            updateStatus("Loaded from IndexedDB! Launching...");
            if (writeToBlank(cachedHtml, BASE_URL)) updateStatus("Launched successfully!");
          } else {
            updateStatus("Downloading game file (~89 MB)...");
            const response = await fetch(RAW_URL);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const text = await response.text();
            if (text.trim().startsWith("version https://git-lfs.github.com/spec/v1")) {
              throw new Error("Received LFS pointer instead of file.");
            }
            updateStatus("Saving to IndexedDB...");
            await saveGame(db, text);
            updateStatus("Launching...");
            if (writeToBlank(text, BASE_URL)) updateStatus("Launched successfully!");
          }
        } catch (err) {
          console.error(err);
          updateStatus("Error: " + err.message);
        }
      }

      async function handleClear() {
        try {
          updateStatus("Opening IndexedDB...");
          const db = await openDB();
          updateStatus("Clearing stored cache...");
          await clearStoredGame(db);
          updateStatus("Cache cleared successfully!");
        } catch (err) {
          console.error(err);
          updateStatus("Error clearing cache: " + err.message);
        }
      }

      setTab(null);
      $("tabMc").addEventListener("click", () => setTab(current === "mc" ? null : "mc"));
      $("tabBr").addEventListener("click", () => setTab(current === "br" ? null : "br"));
      $("backGroup").addEventListener("click", () => setTab(null));
      $("launchGroup").addEventListener("click", handleLaunch);
      $("clearGroup").addEventListener("click", handleClear);
      $("vaultGroup").addEventListener("click", () => { if (writeToBlank(VAULT_HTML)) updateStatus("The Vault launched!"); });
      $("noctGroup").addEventListener("click", () => { if (writeToBlank(NOCTURNE_HTML)) updateStatus("Nocturne launched!"); });
    })();
